#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    // Doolittle LU factorization without pivoting:
    // A becomes [U in upper triangle incl diag; L in lower triangle excl diag (unit diagonal implied)].
    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];

        // No pivoting: if pivot is zero, the factorization is undefined (division by zero).
        // We leave behavior as-is (will produce inf/nan) to match signature (no error reporting).

        // Compute multipliers for L column k: A[i,k] /= A[k,k] for i>k
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            A[static_cast<size_t>(i) * N + k] /= pivot;
        }

        // Update trailing submatrix: A[i,j] -= A[i,k] * A[k,j] for i>k, j>k
        #pragma omp parallel for schedule(static) collapse(2)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            for (std::ptrdiff_t j = static_cast<std::ptrdiff_t>(k) + 1; j < static_cast<std::ptrdiff_t>(N); ++j) {
                const size_t ii = static_cast<size_t>(i);
                const size_t jj = static_cast<size_t>(j);
                A[ii * N + jj] -= A[ii * N + k] * A[k * N + jj];
            }
        }
        // Implicit barrier at end of each parallel for ensures correctness for next k.
    }
}
